// Turn the Apify search results into a short list Claude can learn from.
// If Apify failed or returned nothing, the script still gets written without it.
const rows = $input.all()
  .map(i => i.json)
  .filter(v => v && v.title)
  .sort((a, b) => (b.viewCount || 0) - (a.viewCount || 0))
  .slice(0, 15)
  .map(v => `- ${v.title} (${v.viewCount ?? '?'} izlenme)`);
return [{ json: { trends: rows.length ? rows.join('\n') : '(trend verisi alınamadı)' } }];

// Claude returns the script as JSON text. Pull the JSON object out (tolerating code
// fences), check the fields the rest of the workflow relies on, and plan the files.
const cfg = $('Kanal ayarları').first().json;
const text = ($input.first().json.content || []).map(c => c.text || '').join('');
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start < 0 || end <= start) throw new Error('Claude yanıtında JSON yok: ' + text.slice(0, 300));
const s = JSON.parse(text.slice(start, end + 1));

for (const key of ['title', 'description', 'narration', 'scenes']) {
  if (!s[key] || (Array.isArray(s[key]) && s[key].length === 0)) throw new Error('Senaryoda eksik alan: ' + key);
}

const runId = new Date().toISOString().replace(/[-:]/g, '').replace(/\..*/, '').replace('T', '-');
const runDir = `${cfg.output_dir}/${runId}`;
const scenes = s.scenes.slice(0, Number(cfg.scene_count) || 6).map((sc, i) => ({
  index: i + 1,
  prompt: typeof sc === 'string' ? sc : sc.prompt,
  file: `${runDir}/scene_${String(i + 1).padStart(2, '0')}.jpg`,
}));

let title = String(s.title).trim();
if (!/#shorts/i.test(title) && title.length <= 90) title += ' #Shorts';
const tags = (Array.isArray(s.tags) ? s.tags : String(s.tags || '').split(','))
  .map(t => String(t).replace(/[<>,]/g, '').trim())
  .filter(Boolean)
  .slice(0, 15);

return [{ json: {
  runId,
  runDir,
  title: title.slice(0, 100),
  description: String(s.description).trim() + '\n\n#Shorts',
  tags: tags.join(','),
  narration: String(s.narration).trim(),
  scenes,
} }];

// ElevenLabs returns the voice as base64 plus per-character timings. Save the audio,
// and turn the timings into word-level ASS subtitles (2-3 words per line, big and
// centred, the usual Shorts caption style).
const s = $('Senaryoyu ayrıştır').first().json;
const cfg = $('Kanal ayarları').first().json;
const tts = $input.first().json;
const al = tts.alignment || tts.normalized_alignment;
if (!tts.audio_base64 || !al) throw new Error('ElevenLabs yanıtında ses veya zamanlama yok');

const words = [];
let cur = null;
for (let i = 0; i < al.characters.length; i++) {
  const ch = al.characters[i];
  if (/\s/.test(ch)) { if (cur) { words.push(cur); cur = null; } continue; }
  if (!cur) cur = { text: '', start: al.character_start_times_seconds[i], end: 0 };
  cur.text += ch;
  cur.end = al.character_end_times_seconds[i];
}
if (cur) words.push(cur);

const maxWords = Number(cfg.caption_words) || 3;
const lines = [];
let group = [];
for (const w of words) {
  group.push(w);
  const len = group.map(g => g.text).join(' ').length;
  if (group.length >= maxWords || len > 18 || /[.!?…,;:]$/.test(w.text)) { lines.push(group); group = []; }
}
if (group.length) lines.push(group);

const ts = t => {
  const cs = Math.max(0, Math.round(t * 100));
  const h = Math.floor(cs / 360000), m = Math.floor(cs / 6000) % 60, sec = Math.floor(cs / 100) % 60, c = cs % 100;
  return `${h}:${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}.${String(c).padStart(2, '0')}`;
};
const esc = t => t.replace(/[{}\\]/g, '');

const header = [
  '[Script Info]', 'ScriptType: v4.00+', 'PlayResX: 1080', 'PlayResY: 1920', 'WrapStyle: 0', '',
  '[V4+ Styles]',
  'Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding',
  'Style: Caption,DejaVu Sans,88,&H00FFFFFF,&H00FFFFFF,&H00000000,&H64000000,-1,0,0,0,100,100,0,0,1,7,2,2,80,80,560,1',
  '', '[Events]',
  'Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text',
];
const events = lines.map((g, i) => {
  const start = g[0].start;
  const next = lines[i + 1];
  const end = next ? Math.min(next[0].start, g[g.length - 1].end + 0.4) : g[g.length - 1].end + 0.4;
  return `Dialogue: 0,${ts(start)},${ts(end)},Caption,,0,0,0,,${esc(g.map(w => w.text).join(' '))}`;
});
const ass = header.concat(events).join('\n') + '\n';

// Binary data as base64 objects; n8n stores them like any other file.
const voice = { data: tts.audio_base64, mimeType: 'audio/mpeg', fileName: 'voice.mp3', fileExtension: 'mp3' };
const subs = { data: Buffer.from(ass, 'utf8').toString('base64'), mimeType: 'text/plain', fileName: 'subs.ass', fileExtension: 'ass' };
return [
  { json: { path: `${s.runDir}/voice.mp3` }, binary: { data: voice } },
  { json: { path: `${s.runDir}/subs.ass`, captionLines: events.length }, binary: { data: subs } },
];

const s = $('Senaryoyu ayrıştır').first().json;
return [{ json: {
  videoId: $input.first().json.id,
  url: `https://youtube.com/shorts/${$input.first().json.id}`,
  title: s.title,
  privacy: $('Kanal ayarları').first().json.privacy,
  runDir: s.runDir,
} }];
